export const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`;
export const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=(s,root=document)=>root.querySelector(s);
const category=id=>categories.find(c=>c.id===id)||categories[0];
const article=id=>state.articles.find(a=>a.id===id);
const categoryIcon=id=>{const c=category(id);return `<span class="category-icon ${c.color}">${icon(c.icon)}</span>`;};
const published=()=>state.articles.filter(a=>a.status==='published');
const initials=name=>name.split(' ').slice(0,2).map(x=>x[0]).join('');
const dateLabel=(date=new Date())=>date.toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'2-digit',year:'numeric'});
const isoToday=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Moscow'});
const plural=(n,one,few,many)=>n%100>=11&&n%100<=14?many:n%10===1?one:n%10>=2&&n%10<=4?few:many;
const mobileMedia=matchMedia('(max-width:760px)');
const formatDate=date=>date?date.split('-').reverse().join('.'):'';
let page='',params=new URLSearchParams(),editorInstance=null,editorModule=null,draftTimer,toastTimer,modalReturnFocus,currentArticleId=null,modalCloseCallback,filterQuery='',pendingImages=0;

export function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
async function safely(fn){try{await fn();}catch(e){console.error(e);toast(e.message||'Не удалось выполнить действие. Попробуйте ещё раз.');}}
const navItems=[['','home','Обзор'],['knowledge','book','База знаний'],['favorites','bookmark','Избранное'],['map','map','Карта офиса'],['people','users','Сотрудники']];
const extraNav=[['assistant','sparkles','ИИ-помощник'],['vault','lock','Хранилище'],['resources','link','Базовые инструменты'],['glossary','help','Словарь терминов']];
const navLink=([href,i,label],mobile=false)=>`<a href="#/${href}" class="${mobile?'':'nav-link '}${(page===href||(href==='knowledge'&&['article','editor','start'].includes(page)))?'active':''}" ${page===href?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${!mobile&&href==='knowledge'?`<span class="count">${published().length}</span>`:''}${!mobile&&href==='assistant'?'<span class="count">β</span>':''}</a>`;
function shell(){
 const label=[...navItems,...extraNav,['settings','settings','Настройки'],['article','book','База знаний'],['editor','edit','Редактор статьи'],['start','rocket','Первые шаги']].find(x=>x[0]===page)?.[2]||'Обзор';
 $('#app').innerHTML=`<aside class="sidebar" aria-label="Главная навигация"><a href="#/" class="brand"><span class="brand-mark">${icon('compass')}</span><span class="brand-name">компас<span style="color:#b4d98b">.</span></span></a><div class="brand-subtitle">БАЗА ЗНАНИЙ IT-ПОДДЕРЖКИ</div><button class="workspace-picker" data-action="centers">${icon('building')}<span>БЦ «Горизонт»<small>Рабочее пространство</small></span>${icon('down')}</button><div class="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav>${navItems.map(x=>navLink(x)).join('')}</nav><div class="nav-secondary"><div class="nav-label">ИНСТРУМЕНТЫ</div><nav>${extraNav.map(x=>navLink(x)).join('')}</nav></div><div class="sidebar-spacer"></div><div class="sidebar-note">${icon('shield')}<h3>Знания внутри команды</h3><p>Ваш опыт сегодня — чьё-то<br>решение завтра.</p><div class="online"><span class="dot"></span><span>${serverBacked?'Синхронизация включена':'Локальный режим'}</span></div></div><a href="#/settings" class="nav-link ${page==='settings'?'active':''}">${icon('settings')}<span>Настройки</span></a><button class="profile" data-action="profile"><span class="avatar">АМ</span><span><span class="profile-name">Алексей Морозов</span><span class="profile-role" style="display:block">Администратор</span></span>${icon('down')}</button></aside><div class="app-shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><div class="breadcrumbs"><span class="parent">Рабочее пространство</span>${icon('chevron')}<strong>${label}</strong></div><div class="top-actions"><button class="top-search" data-action="search">${icon('search')}<span>Быстрый поиск</span><kbd>Ctrl K</kbd></button><span class="top-divider"></span><span class="top-date">21 октября, среда</span><button class="icon-btn notification" data-action="notifications" aria-label="Обновления базы знаний">${icon('bell')}</button><button data-action="profile" aria-label="Профиль пользователя"><span class="avatar green">АМ</span></button></div></header><main id="main-content" class="content" tabindex="-1"></main><nav class="mobile-nav" aria-label="Быстрая навигация">${[navItems[0],navItems[1],navItems[3],extraNav[0]].map(x=>navLink(x,true)).join('')}<a href="#/editor" aria-label="Добавить статью">${icon('plus')}<span>Добавить</span></a></nav></div>`;
 $('.top-date').textContent=new Date().toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'long',weekday:'long'}).replace(/ г\.$/,'');
 syncSidebar();
}
function syncSidebar(){const side=$('.sidebar');if(side){side.inert=mobileMedia.matches&&!side.classList.contains('open');side.setAttribute('aria-hidden',String(side.inert));}}
mobileMedia.addEventListener('change',syncSidebar);
const footer=()=>`<footer class="page-footer"><span>${icon('compass')}Компас · Помогаем поддержке находить решения</span><span><span class="dot"></span>Данные хранятся в ${storageLabel()}</span></footer>`;
const titleRow=(title,lead='',action=true)=>`<div class="page-title-row"><div><h1>${title}</h1>${lead?`<p class="page-lead">${lead}</p>`:''}</div>${action?`<a href="#/editor" class="btn btn-primary">${icon('plus')}<span>Создать <span class="desktop-label">статью</span></span></a>`:''}</div>`;
