function articleRow(a){return `<a href="#/article/${a.id}" class="article-row"><span class="category-icon">${icon('file')}</span><div class="article-row-main"><h3>${esc(a.title)}</h3><div class="article-meta"><span>${category(a.category).name}</span><span>·</span><span>${a.minutes} мин чтения</span><span>·</span><span>${a.date}</span></div></div>${a.pinned?'<span class="badge">Рекомендуем</span>':''}${icon('chevron')}</a>`;}
function guideCard(a){return `<article class="guide-card"><div class="guide-card-top">${categoryIcon(a.category)}<button class="icon-btn ${state.favorites.includes(a.id)?'saved':''}" data-action="favorite" data-id="${a.id}" aria-label="${state.favorites.includes(a.id)?'Убрать из избранного':'В избранное'}" aria-pressed="${state.favorites.includes(a.id)}">${icon('bookmark')}</button></div><a href="#/article/${a.id}"><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p></a><div class="guide-card-bottom"><span>${category(a.category).name}</span><span class="flex">${icon('clock')}${a.minutes} мин</span></div></article>`;}
function renderHome(){
 $('#main-content').innerHTML=`<div class="page-title-row"><div><p class="greeting">С возвращением, Алексей <span class="welcome-hand">☀</span></p><h1>Всё под рукой.</h1></div><a href="#/editor" class="btn btn-primary">${icon('plus')}<span>Создать <span class="desktop-label">статью</span></span></a></div><section class="hero"><div class="hero-copy"><div class="eyebrow">ВАШ ОРИЕНТИР В IT-ПОДДЕРЖКЕ</div><h2>Меньше поисков.<br><span>Больше решений.</span></h2><p>Инструкции, контакты и опыт команды —<br>чтобы разобраться на месте.</p><button class="hero-search" data-action="search">${icon('search')}<span>Что ищем? Проблема, программа или оборудование</span><kbd>Ctrl K</kbd></button></div>${compassArt()}<div class="hero-note">${icon('shield')}Знания, которые остаются с командой</div></section><div class="overview-grid"><div><section><div class="section-heading"><h2>С чего начнём?</h2><a class="text-link" href="#/knowledge">Все разделы ${icon('arrow')}</a></div><div class="category-grid">${categories.map(c=>`<a href="#/knowledge?category=${c.id}" class="category-card"><span class="category-icon ${c.color}">${icon(c.icon)}</span><h3>${c.name}</h3><p>${c.desc}</p><div class="category-bottom"><span>${published().filter(a=>a.category===c.id).length} статьи</span>${icon('arrow')}</div></a>`).join('')}</div></section><section class="recent-section"><div class="section-heading"><h2>Недавно обновили</h2><a href="#/knowledge?sort=updated" class="text-link">Все статьи ${icon('arrow')}</a></div><div class="article-list">${sortedArticles().slice(0,4).map(articleRow).join('')}</div></section></div><aside class="overview-aside"><section class="start-card"><div class="eyebrow">${icon('rocket')}ПЕРВЫЙ ДЕНЬ В КОМАНДЕ?</div><h2>Начните<br>с простого.</h2><p>Разберитесь, как всё устроено.<br>От первого подключения<br>до самостоятельной заявки.</p><a href="#/start" class="btn btn-lime">Маршрут новичка ${icon('arrow')}</a></section><section class="quick-section"><h2>Быстрый доступ</h2><div class="quick-links"><a href="#/map" class="quick-link">${icon('map')}Найти рабочее место${icon('external')}</a><a href="#/people" class="quick-link">${icon('users')}Контакты сотрудников${icon('external')}</a><a href="#/article/new-workplace" class="quick-link">${icon('clipboard')}Новое рабочее место${icon('external')}</a><button class="quick-link" data-action="integration" data-id="itilium">${icon('link')}Система заявок${icon('external')}</button></div></section><section class="activity-card"><h2>Жизнь базы знаний</h2>${sortedArticles().slice(0,3).map((a,i)=>`<div class="activity"><span class="avatar ${['green','purple','blue'][i]}">${initials(a.author)}</span><div><p><strong>${esc(a.author.split(' ')[0])}</strong> ${a.revisions.length>1?'обновил(а) статью':'добавил(а) статью'}</p><a href="#/article/${a.id}">${esc(a.title)}</a><time>${a.date}</time></div></div>`).join('')}</section></aside></div>${footer()}`;
}
function sortedArticles(){return [...published()].sort((a,b)=>(b.date.split('.').reverse().join('')).localeCompare(a.date.split('.').reverse().join('')));}
function renderLibrary(){
 const favoritePage=page==='favorites',draftView=params.get('tab')==='drafts';
 $('#main-content').innerHTML=`${titleRow(favoritePage?'Всегда под рукой.':'База знаний',favoritePage?'Ваши сохранённые инструкции и полезные материалы.':'Опыт команды, собранный в понятные инструкции.')}<div class="page-tabs"><a class="tab ${!draftView?'active':''}" href="#/${favoritePage?'favorites':'knowledge'}">${favoritePage?'Сохранённые':'Все статьи'} <span>${favoritePage?state.favorites.filter(id=>article(id)).length:published().length}</span></a>${!favoritePage?`<a class="tab ${draftView?'active':''}" href="#/knowledge?tab=drafts">Черновики <span>${Object.keys(state.drafts).length}</span></a>`:''}</div>${draftView?'<div id="library-results"></div>':`<div class="toolbar"><label class="search-field">${icon('search')}<input id="library-search" type="search" placeholder="Найти инструкцию…" aria-label="Поиск по статьям" value="${esc(params.get('q')||'')}"></label><select class="field-select" id="department-filter" aria-label="Отдел"><option value="">Все отделы</option><option>Бухгалтерия</option><option>Отдел продаж</option><option>Отдел кадров</option><option>IT-поддержка</option></select><select class="field-select" id="sort-filter" aria-label="Сортировка"><option value="updated">Сначала новые</option><option value="title">По названию</option><option value="minutes">Быстрые инструкции</option></select></div><div class="chip-row"><button class="chip ${!params.get('category')?'active':''}" data-action="category-filter" data-id="">Все разделы</button>${categories.map(c=>`<button class="chip ${params.get('category')===c.id?'active':''}" data-action="category-filter" data-id="${c.id}">${icon(c.icon)}${c.name}</button>`).join('')}</div><div id="library-results"></div>`}${footer()}`;
 if(draftView){const drafts=Object.entries(state.drafts);$('#library-results').innerHTML=drafts.length?`<div class="article-list">${drafts.map(([id,d])=>`<div class="article-row"><span class="category-icon">${icon('edit')}</span><a class="article-row-main" href="#/editor/${id==='new'?'':id}"><h3>${esc(d.title||'Без названия')}</h3><div class="article-meta">Черновик · ${esc(d.savedAt||'')}</div></a><button class="icon-btn" data-action="delete-draft" data-id="${id}" aria-label="Удалить черновик">${icon('trash')}</button></div>`).join('')}</div>`:emptyState('Черновики пока не созданы','Новая статья сохранится здесь автоматически, пока вы её пишете.','edit','Создать статью','#/editor');}
 else{filterQuery=params.get('q')||'';updateLibrary();$('#library-search').addEventListener('input',e=>{filterQuery=e.target.value;updateLibrary();});$('#sort-filter').addEventListener('change',updateLibrary);$('#department-filter').addEventListener('change',updateLibrary);}
}
function updateLibrary(){let items=searchArticles(filterQuery);if(page==='favorites')items=items.filter(a=>state.favorites.includes(a.id));const cat=params.get('category');if(cat)items=items.filter(a=>a.category===cat);const dep=$('#department-filter')?.value;if(dep)items=items.filter(a=>a.department==='Все отделы'||a.department===dep);const sort=$('#sort-filter')?.value;items.sort(sort==='title'?(a,b)=>a.title.localeCompare(b.title,'ru'):sort==='minutes'?(a,b)=>a.minutes-b.minutes:(a,b)=>b.date.split('.').reverse().join('').localeCompare(a.date.split('.').reverse().join('')));$('#library-results').innerHTML=items.length?`<div class="library-grid">${items.map(guideCard).join('')}</div>`:emptyState(page==='favorites'?'Здесь будут ваши инструкции':'Ничего не нашлось',page==='favorites'?'Нажмите на закладку у полезной статьи, и она появится здесь.':'Попробуйте другое слово или выберите другой раздел.','book','Открыть все статьи','#/knowledge');}
function emptyState(title,description,i='search',label,href){return `<div class="empty"><span class="category-icon green">${icon(i)}</span><h2>${title}</h2><p>${description}</p>${label?`<a class="btn" href="${href}">${label}${icon('arrow')}</a>`:''}</div>`;}
function renderArticle(){const a=article(currentArticleId);if(!a){$('#main-content').innerHTML=emptyState('Статья не найдена','Она могла быть удалена или ссылка изменилась.','file','Перейти в базу знаний','#/knowledge');return;}
 const safe=sanitize(a.body);const doc=new DOMParser().parseFromString(safe,'text/html');doc.querySelectorAll('h2,h3').forEach((h,i)=>h.id=`section-${i}`);const headings=[...doc.querySelectorAll('h2,h3')];
 $('#main-content').innerHTML=`<a href="#/knowledge" class="back-link">${icon('back')}В базу знаний</a><div class="guide-layout"><article class="guide-document"><div class="between"><span class="badge">${category(a.category).name}</span><span class="badge neutral">Версия ${a.revisions.length}</span></div><h1>${esc(a.title)}</h1><div class="guide-details"><span class="flex gap8"><span class="avatar green">${initials(a.author)}</span>${esc(a.author)}</span><span class="flex gap8">${icon('clock')}${a.minutes} мин чтения</span><span>Обновлено ${a.date}</span></div><div class="effective">${icon('check')}Действует с ${formatDate(a.effective)} · ${esc(a.department)}</div><div class="prose" id="article-content">${doc.body.innerHTML}</div><div class="helpful"><span>Инструкция помогла разобраться?</span><button class="btn btn-small" data-action="helpful" data-id="${a.id}">${icon('thumb')}Да, спасибо</button></div></article><aside class="guide-aside"><div class="panel"><div class="guide-action-row"><a class="btn btn-primary btn-small" href="#/editor/${a.id}">${icon('edit')}Редактировать</a><button class="btn btn-small" data-action="favorite" data-id="${a.id}" aria-label="${state.favorites.includes(a.id)?'Убрать из избранного':'Добавить в избранное'}" aria-pressed="${state.favorites.includes(a.id)}">${icon('bookmark')}</button></div><button class="btn btn-quiet btn-small" style="width:100%;margin-top:7px" data-action="history" data-id="${a.id}">${icon('history')}История изменений</button></div><div class="panel toc-panel"><h3>В этой инструкции</h3>${headings.map((h,i)=>`<a class="toc-link" href="#section-${i}" data-action="toc" data-id="section-${i}">${esc(h.textContent)}</a>`).join('')}</div><div class="panel"><h3>Контекст инструкции</h3><p class="tiny muted" style="line-height:1.9">${esc(a.center)}<br>${esc(a.department)}<br>${a.tags.map(esc).join(' · ')}</p><button class="text-link" style="font-size:12px;margin-top:16px" data-action="copy-link" data-id="${a.id}">${icon('link')}Скопировать ссылку</button></div></aside></div>${footer()}`;
}
function renderStart(){const ids=['network-basics','phone-pc','new-workplace','ticket'];$('#main-content').innerHTML=`${titleRow('Ваш маршрут в поддержке.','Не нужно знать всё в первый день. Начнём с основ.',false)}<div class="notice">${icon('info')}Это вводная подборка. Внутренние регламенты, подсети и контакты вашей компании необходимо добавить отдельно.</div>${ids.map((id,i)=>{const a=article(id);return a?`<article class="onboard-card"><span class="step-number">0${i+1}</span><div><h2>${esc(a.title)}</h2><p>${esc(a.summary)}</p><a href="#/article/${id}" class="text-link">Открыть инструкцию · ${a.minutes} мин ${icon('arrow')}</a></div></article>`:'';}).join('')}<div class="panel"><h2 style="font-size:19px;margin-bottom:10px">Не знаете слово? Это нормально.</h2><p class="muted tiny">Собрали термины без сложных объяснений.</p><a href="#/glossary" class="text-link" style="margin-top:15px">Открыть словарь ${icon('arrow')}</a></div>${footer()}`;}

function officeOptions(){return{icon,esc,toast,showModal,closeModal,titleRow,footer,params};}
function renderPeople(){mountPeople(officeOptions());}
function renderMap(){mountMap(officeOptions());}
const integrations={
 itilium:{name:'Итилиум',desc:'Система заявок и решений из 1С.',icon:'clipboard',color:'blue',detail:'Здесь появится переход к вашей системе заявок и привязка инструкций к решениям. Адрес сервиса и способ интеграции задаются после согласования.'},
 directory:{name:'Каталог сотрудников',desc:'Сотрудники, отделы и оборудование.',icon:'users',color:'purple',detail:'Подготовлено место для подключения корпоративного каталога сотрудников.'},
 vault:{name:'Хранилище доступов',desc:'Пароли устройств через защищённый сервис.',icon:'lock',color:'yellow',detail:'Секреты не сохраняются в статьях и браузере. Здесь будет подключён корпоративный менеджер паролей с серверной проверкой прав и журналом обращений.'},
 ad:{name:'Active Directory',desc:'Учётные записи и группы доступа.',icon:'network',color:'green',detail:'Подключение к домену будет работать через внутренний серверный шлюз. Для справочной системы достаточно режима чтения в пределах утверждённых полномочий.'},
 files:{name:'Корпоративные ресурсы',desc:'Общие папки и внутренние порталы.',icon:'link',color:'peach',detail:'Добавьте разрешённую ссылку на внутренний портал или папку. Сайт не выдаёт права доступа к ресурсу; они согласуются отдельно.'}
};
function renderResources(){
 $('#main-content').innerHTML=`${titleRow('Базовые инструменты','Ссылки и сервисы команды.',false)}<div class="between" style="margin-bottom:22px"><span class="muted tiny">Ссылки, которыми пользуется поддержка</span><button class="btn btn-small btn-primary" data-action="add-link">${icon('plus')}Добавить ссылку</button></div><div class="resource-grid">${state.links.map(l=>`<article class="resource-card"><span class="category-icon green">${icon('link')}</span><div style="flex:1"><div class="between"><h3>${esc(l.title)}</h3><div class="resource-actions"><button class="icon-btn" data-action="edit-link" data-id="${l.id}" aria-label="Изменить ссылку">${icon('edit')}</button><button class="icon-btn" data-action="delete-link" data-id="${l.id}" aria-label="Удалить ссылку">${icon('trash')}</button></div></div><p>${esc(l.description)}</p><a class="btn btn-small" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">Открыть ресурс ${icon('external')}</a></div></article>`).join('')||`<div class="empty"><span class="category-icon green">${icon('link')}</span><h2>Пока нет ссылок</h2><p>Добавьте адреса, которые нужны команде каждый день.</p><button class="btn btn-primary" data-action="add-link">${icon('plus')}Добавить ссылку</button></div>`}</div>${footer()}`;
}
function renderGlossary(){
 $('#main-content').innerHTML=`${titleRow('Знакомые слова. Новый контекст.','Коротко о том, как устроена корпоративная IT-среда.',false)}<div class="panel">${glossary.map(([word,description,id])=>`<article class="glossary-card"><h3>${word}</h3><p>${description}</p><a href="#/article/${id}" class="text-link">Подробнее в инструкции ${icon('arrow')}</a></article>`).join('')}</div>${footer()}`;
}
function renderAssistant(){
 $('#main-content').innerHTML=`<div class="ai-wrap"><div class="between"><span class="badge purple">${icon('sparkles')}ИИ-помощник</span><a href="#/settings?tab=ai" class="text-link">${icon('settings')}Настройки</a></div><section class="ai-empty"><div class="ai-symbol">${icon('sparkles')}</div><h1>Разберёмся вместе.</h1><p>Задайте вопрос своими словами. Помощник ответит по материалам базы и покажет, на какие статьи опирался.</p></section><div class="ai-suggestions">${['Как подготовить рабочее место?','Outlook не подключается','Принтер не печатает','Доступ к общей папке'].map(t=>`<button class="suggestion" data-action="suggest" data-query="${esc(t)}">${t}${icon('arrow')}</button>`).join('')}</div><form id="ai-form" class="ai-composer"><textarea id="ai-query" placeholder="Например: как подключить компьютер через телефон?" aria-label="Ваш вопрос" required></textarea><div class="ai-composer-bottom"><span class="flex gap8">${icon('shield')}Контекст остаётся на сервере Compass</span><button class="btn btn-primary" type="submit">Задать вопрос ${icon('arrow')}</button></div></form><div id="ai-results" class="ai-results"></div><div class="notice" style="margin-top:28px">${icon('info')}Для ответа нужен ключ провайдера в настройках ИИ. Пока ключ не задан, работает обычный поиск по базе.</div></div>${footer()}`;
 $('#ai-form').addEventListener('submit',e=>{e.preventDefault();runAssistantSearch();});
}
async function runAssistantSearch(){const q=$('#ai-query').value.trim();if(!q)return;const terms=q.toLocaleLowerCase('ru').match(/[а-яёa-z0-9]{4,}/g)||[];const scored=published().map(a=>{const title=a.title.toLocaleLowerCase('ru');const all=(a.title+' '+a.summary+' '+textContent(a.body)).toLocaleLowerCase('ru');return{a,score:terms.reduce((s,t)=>s+(title.includes(t)?3:all.includes(t)?1:0),0)};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,4).map(x=>x.a);const context=scored.map(a=>`Статья: ${a.title}\n${a.summary}\n${textContent(a.body).slice(0,1800)}`).join('\n\n');$('#ai-results').innerHTML=`<div class="ai-loading">${icon('sparkles')}Готовлю ответ…</div>`;try{const response=await fetch('/api/assistant/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,context})});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'Провайдер пока не настроен.');$('#ai-results').innerHTML=`<article class="ai-message"><div class="ai-message-heading">${icon('sparkles')}Ответ помощника</div><div class="prose">${esc(payload.text).replace(/\n/g,'<br>')}</div>${scored.length?`<div class="ai-sources"><strong>Источники</strong>${scored.map(a=>`<a href="#/article/${a.id}">${esc(a.title)} ${icon('arrow')}</a>`).join('')}</div>`:''}</article>`;}catch(error){$('#ai-results').innerHTML=`<h2>Материалы по вашему вопросу</h2><p class="tiny muted" style="margin-bottom:15px">${esc(error.message)} Ниже — локальный поиск по базе.</p>${scored.length?`<div class="article-list">${scored.map(articleRow).join('')}</div>`:emptyState('В базе пока нет ответа','Уточните запрос или добавьте новую инструкцию.','search','Создать статью','#/editor')}`;}}
function renderSettings(){const tab=params.get('tab')||'general';
 $('#main-content').innerHTML=`${titleRow('Настроим под вашу команду.','Рабочее пространство, пользователи и будущие интеграции.',false)}<div class="settings-layout"><nav class="settings-menu">${[['general','settings','Общее'],['users','users','Пользователи'],['integrations','link','Интеграции'],['ai','sparkles','ИИ-помощник']].map(([id,i,label])=>`<a href="#/settings?tab=${id}" class="nav-link ${tab===id?'active':''}">${icon(i)}${label}</a>`).join('')}</nav><div class="settings-content" id="settings-content"></div></div>${footer()}`;
 const target=$('#settings-content');
 if(tab==='users')target.innerHTML=`<section class="panel"><div class="between"><h2>Команда <span class="badge neutral">${state.users.length}</span></h2><button class="btn btn-primary btn-small" data-action="add-user">${icon('plus')}Добавить</button></div><table class="users-table"><thead><tr><th>Сотрудник</th><th>Роль</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><div class="flex gap12"><span class="avatar green">${esc(u.initials)}</span><div>${esc(u.name)}<small>${esc(u.email)}</small></div></div></td><td><select data-role-user="${u.id}" aria-label="Роль ${esc(u.name)}" ${u.id==='u1'?'disabled':''}><option value="admin" ${u.role==='admin'?'selected':''}>Администратор</option><option value="user" ${u.role==='user'?'selected':''}>Сотрудник</option></select></td><td>${u.id!=='u1'?`<button class="icon-btn" data-action="delete-user" data-id="${u.id}" aria-label="Удалить ${esc(u.name)}">${icon('trash')}</button>`:''}</td></tr>`).join('')}</tbody></table></section>`;
 else if(tab==='integrations')target.innerHTML=`<section class="panel"><h2>Сервисы компании</h2><p>Подготовленные точки подключения. Секреты и доменные подключения должны находиться на внутреннем сервере.</p><div class="settings-rows">${Object.entries(integrations).map(([id,r])=>`<div class="setting-row"><div><h3>${r.name}</h3><p>${r.desc}</p></div><button class="btn btn-small" data-action="integration" data-id="${id}">Подробнее ${icon('arrow')}</button></div>`).join('')}</div></section>`;
 else if(tab==='ai')target.innerHTML=`<section class="panel"><h2>Провайдер ИИ</h2><p>Ключ хранится только на сервере Compass. Настраивать провайдера может администратор.</p><form id="ai-settings-form" class="settings-form"><div class="field"><label for="ai-provider">Провайдер</label><select id="ai-provider"><option value="gigachat">GigaChat · рекомендован для России</option><option value="openai">OpenAI-compatible · DeepSeek и другие</option><option value="custom">Свой OpenAI-compatible API</option></select></div><div class="field"><label for="ai-model">Модель</label><input id="ai-model" placeholder="Например: GigaChat-2-Max"></div><div class="field"><label for="ai-base-url">API base URL</label><input id="ai-base-url" placeholder="https://…/v1"></div><div class="field"><label for="ai-key">API-ключ</label><input id="ai-key" type="password" autocomplete="new-password" placeholder="Оставьте пустым, чтобы сохранить текущий"></div><div id="ai-settings-status" class="field-help">Провайдер ещё не настроен.</div><div class="modal-footer"><button class="btn btn-primary" type="submit">${icon('check')}Сохранить настройки</button></div></form><div class="notice">${icon('shield')}В запрос уходит только вопрос и найденный контекст статей. Пароли, скрытые поля хранилища и персональные секреты не отправляются.</div></section>`;
 else target.innerHTML=`<section class="panel"><h2>Рабочее пространство</h2><p>Компас · БЦ «Горизонт»</p><div class="settings-rows"><div class="setting-row"><div><h3>Хранение данных</h3><p>Статьи, черновики, картинки, сотрудники, карта и настройки сохраняются в ${storageLabel()}.</p></div><span class="badge ${persistent?'':'amber'}">${persistent?(serverBacked?'PostgreSQL':'Локальное'):'Недоступно'}</span></div><div class="setting-row"><div><h3>Синхронизация</h3><p>${serverBacked?'Данные доступны этому серверу и могут использоваться несколькими клиентами.':'Для общей работы запустите PostgreSQL и задайте COMPASS_DATABASE_URL.'}</p></div><span class="badge ${serverBacked?'':'amber'}">${serverBacked?'Подключена':'Ожидает настройки'}</span></div><div class="setting-row"><div><h3>Резервная копия</h3><p>Экспортируйте статьи, версии, черновики, ссылки и настройки в JSON.</p></div><button class="btn btn-small" data-action="export">${icon('download')}Экспорт</button></div></div></section><section class="panel"><h2>Читаемо на любом экране</h2><p>Интерфейс адаптируется к телефону, планшету и компьютеру. Размер текста и элементов увеличен для больших мониторов.</p><a href="#/start" class="text-link">Открыть маршрут новичка ${icon('arrow')}</a></section>`;
 target.querySelectorAll('[data-role-user]').forEach(el=>el.addEventListener('change',()=>safely(async()=>{await update(s=>{s.users.find(u=>u.id===el.dataset.roleUser).role=el.value;});toast('Роль обновлена');})));
 if(tab==='ai')loadAiSettings();
}
async function loadAiSettings(){const form=$('#ai-settings-form');if(!form)return;try{const response=await fetch('/api/ai/settings',{cache:'no-store'});if(!response.ok)return;const data=await response.json();$('#ai-provider').value=data.provider||'gigachat';$('#ai-model').value=data.model||'';$('#ai-base-url').value=data.baseUrl||'';$('#ai-settings-status').textContent=data.configured?'Ключ сохранён на сервере. Для замены введите новый.':'Ключ ещё не задан.';}catch{}}

async function renderEditor(){
 const a=currentArticleId?article(currentArticleId):null;
 if(currentArticleId&&!a){$('#main-content').innerHTML=emptyState('Статья не найдена','Вернитесь в базу знаний.','file','Открыть базу','#/knowledge');return;}
 const draft=state.drafts[currentArticleId||'new'];const d=draft||a||{title:'',summary:'',body:'',category:'workplace',department:'Все отделы',effective:isoToday(),tags:[],note:''};
 $('#main-content').innerHTML=`<div class="editor-page"><div class="editor-header"><a href="${a?'#/article/'+a.id:'#/knowledge'}" class="back-link">${icon('back')}${a?'К статье':'В базу знаний'}</a><div class="flex gap12"><span class="editor-status" id="draft-status">${icon('check')}${draft?'Черновик восстановлен':'Готово к работе'}</span><button class="btn btn-small" data-action="preview">${icon('eye')}Предпросмотр</button><button class="btn btn-primary btn-small" id="publish-button" data-action="publish">${icon('check')}${a?'Сохранить версию':'Опубликовать'}</button></div></div><div id="editor-duplicates"></div><section class="editor-paper"><div class="editor-meta"><div class="field"><label for="editor-category">Раздел</label><select id="editor-category">${categories.map(c=>`<option value="${c.id}" ${d.category===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="field"><label for="editor-department">Для какого отдела</label><select id="editor-department">${['Все отделы','Бухгалтерия','Отдел продаж','Отдел кадров','IT-поддержка'].map(dep=>`<option ${d.department===dep?'selected':''}>${dep}</option>`).join('')}</select></div><div class="field"><label for="editor-effective">Начало действия</label><input type="date" id="editor-effective" value="${esc(d.effective)}" required></div></div><textarea id="editor-title" class="editor-title" rows="2" maxlength="180" aria-label="Название статьи" placeholder="Название, которое легко найти">${esc(d.title)}</textarea><textarea id="editor-summary" class="editor-summary" rows="2" maxlength="500" aria-label="Краткое описание" placeholder="Коротко: какую проблему решает эта инструкция?">${esc(d.summary)}</textarea><div class="editor-toolbar" id="editor-toolbar" role="toolbar" aria-label="Форматирование текста"></div><div class="table-actions hidden" id="table-actions">${[['addRowAfter','+ Строка'],['addColumnAfter','+ Столбец'],['deleteRow','Удалить строку'],['deleteColumn','Удалить столбец'],['deleteTable','Удалить таблицу']].map(([cmd,title])=>`<button class="btn btn-small" data-table-command="${cmd}">${title}</button>`).join('')}</div><div class="table-actions hidden" id="code-actions"><span class="tiny muted">Блок кода · Enter — новая строка · Ctrl Enter — выйти из блока</span></div><div class="editor-body" id="editor-body"></div><div class="editor-foot"><span id="word-count">0 слов</span><span>${icon('image')}Картинку можно вставить, загрузить или перетащить</span></div></section><div class="editor-options"><div class="field"><label for="editor-tags">Метки через запятую</label><input id="editor-tags" value="${esc((d.tags||[]).join(', '))}" placeholder="Например: Outlook, Диагностика"></div><div class="field"><label for="editor-note">${a?'Что изменилось в этой версии?':'Комментарий к публикации'}</label><input id="editor-note" maxlength="500" value="${esc(draft?.note||'')}" placeholder="Например: новый порядок с 21 октября"></div></div><p class="editor-hint">${icon('shield')}Черновик сохраняется автоматически. Не добавляйте пароли и служебные данные в статьи. Для вставки ссылки выделите текст и нажмите Ctrl K.</p></div>`;
 editorModule ||= await import('./editor.js');
 if(page!=='editor')return;
 editorInstance=editorModule.createEditor({element:$('#editor-body'),toolbar:$('#editor-toolbar'),content:sanitize(d.body),icon,onChange:editorChanged,onLink:showLinkDialog,onError:toast,onImageState:n=>{pendingImages+=n;const b=$('#publish-button');if(b)b.disabled=pendingImages>0;}});
 document.querySelectorAll('#editor-title,#editor-summary,#editor-tags,#editor-note,#editor-category,#editor-department,#editor-effective').forEach(el=>el.addEventListener('input',()=>{editorChanged();if(el.id==='editor-title')checkSimilar();}));
 updateWordCount();checkSimilar();
}
function collectDraft(){if(!editorInstance||!$('#editor-title'))return null;return{title:$('#editor-title').value,summary:$('#editor-summary').value,body:sanitize(editorInstance.getHTML()),category:$('#editor-category').value,department:$('#editor-department').value,effective:$('#editor-effective').value,tags:$('#editor-tags').value.split(',').map(t=>t.trim()).filter(Boolean).slice(0,15),note:$('#editor-note').value,savedAt:dateLabel()};}
function editorChanged(){if(!editorInstance)return;$('#draft-status').innerHTML=`${icon('clock')}Сохраняем…`;updateWordCount();clearTimeout(draftTimer);draftTimer=setTimeout(()=>safely(saveDraft),650);}
async function saveDraft(){const d=collectDraft();if(!d||(!d.title.trim()&&!textContent(d.body).trim()&&!d.body.includes('<img')))return;const key=currentArticleId||'new';await update(s=>{s.drafts[key]=d;});if($('#draft-status'))$('#draft-status').innerHTML=`${icon('check')}Черновик сохранён`;}
function updateWordCount(){const text=editorInstance?.getText()||'';const el=$('#word-count');if(el)el.textContent=`${text.trim()?text.trim().split(/\s+/).length:0} слов · ${text.length} символов`;}
function checkSimilar(){const title=$('#editor-title')?.value||'';const found=similarArticles(title,currentArticleId);const target=$('#editor-duplicates');if(target)target.innerHTML=found.length?`<div class="duplicates"><strong>${icon('info')}Есть похожие материалы</strong><p style="font-size:12px;margin-top:6px">Возможно, удобнее дополнить существующую инструкцию. Проверка по словам, без ИИ.</p>${found.map(a=>`<a href="#/article/${a.id}">${esc(a.title)} ${icon('external')}</a>`).join('')}</div>`:'';}
function showLinkDialog(editor){const current=editor.getAttributes('link').href||'';showModal('Вставить ссылку',`<form id="link-form"><div class="field"><label for="link-url">Адрес</label><input type="url" id="link-url" placeholder="https://…" value="${esc(current)}" required></div><p class="tiny muted">Ссылка применится к выделенному тексту. Если текст не выделен, вставится сам адрес.</p><div class="modal-footer">${current?'<button type="button" class="btn" data-action="unlink">Убрать ссылку</button>':''}<button type="button" class="btn" data-action="close-modal">Отмена</button><button class="btn btn-primary" type="submit">Вставить</button></div></form>`);$('#link-form').addEventListener('submit',e=>{e.preventDefault();const href=$('#link-url').value.trim();if(!/^https?:\/\//i.test(href)){toast('Укажите адрес с http:// или https://');return;}const {empty}=editor.state.selection;closeModal();if(empty)editor.chain().focus().insertContent({type:'text',text:href,marks:[{type:'link',attrs:{href,target:'_blank',rel:'noopener noreferrer'}}]}).run();else editor.chain().focus().extendMarkRange('link').setLink({href}).run();});}
async function publish(skipSimilar=false){
 if(pendingImages){toast('Подождите, изображения ещё загружаются');return;}
 const d=collectDraft();if(!d)return;d.title=d.title.trim();d.summary=d.summary.trim();
 if(!d.title){toast('Добавьте название статьи');$('#editor-title').focus();return;}
 if(!textContent(d.body).trim()&&!d.body.includes('<img')){toast('Добавьте содержание инструкции');editorInstance.commands.focus();return;}
 if(!d.effective||!/^\d{4}-\d{2}-\d{2}$/.test(d.effective)||!$('#editor-effective').checkValidity()){toast('Укажите дату начала действия');$('#editor-effective').focus();return;}
 if(!d.summary)d.summary=textContent(d.body).slice(0,160);
 const similar=similarArticles(d.title,currentArticleId);
 if(!skipSimilar&&similar.length){showModal('Похоже, это уже есть в базе',`<p>Найдены статьи с похожими словами. Можно открыть существующую и дополнить её или опубликовать отдельную инструкцию.</p><div class="article-list">${similar.map(articleRow).join('')}</div><div class="modal-footer"><button class="btn" data-action="close-modal">Продолжить редактировать</button><button class="btn btn-primary" data-action="publish-anyway">Опубликовать отдельно</button></div>`);await saveDraft();return;}
 const a=currentArticleId?article(currentArticleId):null;const id=a?.id||crypto.randomUUID();const date=dateLabel();const author='Алексей Морозов';
 const unchanged=a&&['title','summary','body','category','department','effective'].every(k=>a[k]===d[k])&&JSON.stringify(a.tags)===JSON.stringify(d.tags);
 if(unchanged){toast('Изменений нет');location.hash=`#/article/${id}`;return;}
 const revision={version:(a?.revisions.length||0)+1,date,author,title:d.title,summary:d.summary,body:d.body,effective:d.effective,department:d.department,category:d.category,tags:d.tags,note:d.note.trim()||(a?'Обновление инструкции':'Первая публикация')};
 await update(s=>{const record={...a,...d,id,date,author,status:'published',center:'БЦ «Горизонт»',minutes:Math.max(1,Math.ceil(textContent(d.body).split(/\s+/).length/170)),pinned:a?.pinned||false,views:a?.views||0,revisions:[...(a?.revisions||[]),revision]};delete record.savedAt;delete record.note;const index=s.articles.findIndex(x=>x.id===id);if(index>=0)s.articles[index]=record;else s.articles.unshift(record);delete s.drafts[currentArticleId||'new'];});
 clearTimeout(draftTimer);editorInstance.destroy();editorInstance=null;closeModal();toast(a?'Новая версия сохранена. История доступна в статье.':'Статья опубликована');location.hash=`#/article/${id}`;
}

function showModal(title,body,wide=false,onClose){
 if($('#overlay-root').children.length)closeModal(true);modalReturnFocus=document.activeElement;modalCloseCallback=onClose;
 $('#overlay-root').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть окно">${icon('close')}</button></header><div class="modal-body">${body}</div></section></div>`;syncScrollLock();setTimeout(()=>{($('.modal input:not([type=hidden])')||$('.modal textarea')||$('.modal button')||$('.modal a'))?.focus({preventScroll:true});},20);
 $('.overlay').addEventListener('mousedown',e=>{if(e.target===$('.overlay'))closeModal();});
}
let lockedScroll=null,lockedSticky=[];
function freezeStickyPanels(){lockedSticky=[...document.querySelectorAll('.guide-aside,.office-detail,.editor-toolbar')].filter(el=>getComputedStyle(el).position==='sticky'&&el.getClientRects().length).map(el=>({el,style:el.getAttribute('style'),rect:el.getBoundingClientRect(),placeholder:document.createElement('div')}));for(const item of lockedSticky){const {el,rect,placeholder}=item;placeholder.setAttribute('aria-hidden','true');placeholder.style.cssText=`width:${rect.width}px;height:${rect.height}px;visibility:hidden;pointer-events:none;align-self:start`;el.before(placeholder);Object.assign(el.style,{position:'fixed',left:rect.left+'px',top:rect.top+'px',right:'auto',bottom:'auto',width:rect.width+'px',margin:'0'});}}
function restoreStickyPanels(){for(const item of lockedSticky){item.style===null?item.el.removeAttribute('style'):item.el.setAttribute('style',item.style);item.placeholder.remove();}lockedSticky=[];}
function updateLockedHeader(){const header=$('.topbar'),shell=$('.app-shell');if(!header||!shell)return;const left=shell.getBoundingClientRect().left;document.body.style.setProperty('--locked-header-left',left+'px');document.body.style.setProperty('--locked-header-width',(innerWidth-left)+'px');document.body.style.setProperty('--locked-header-height',header.getBoundingClientRect().height+'px');}
function syncScrollLock(){
 const locked=!!$('.modal')||!!$('.sidebar.open');
 if(locked&&!lockedScroll){lockedScroll={x:window.scrollX,y:window.scrollY};updateLockedHeader();freezeStickyPanels();document.body.style.top=-lockedScroll.y+'px';document.body.style.left=-lockedScroll.x+'px';document.documentElement.classList.add('scroll-locked');document.body.classList.add('scroll-locked');}
 else if(!locked&&lockedScroll){const position=lockedScroll;lockedScroll=null;document.documentElement.classList.remove('scroll-locked');document.body.classList.remove('scroll-locked');document.body.style.top='';document.body.style.left='';restoreStickyPanels();window.scrollTo({top:position.y,left:position.x,behavior:'instant'});}
}
window.addEventListener('resize',()=>{if(lockedScroll)updateLockedHeader();});
function closeModal(keepScrollLock=false){if(!$('#overlay-root').children.length)return;hideOfficeSecrets();$('#overlay-root').innerHTML='';if(!keepScrollLock)syncScrollLock();const callback=modalCloseCallback;modalCloseCallback=null;callback?.();if(modalReturnFocus?.isConnected)modalReturnFocus.focus({preventScroll:true});}
function openSearch(){showModal('Поиск','');const modal=$('.modal');modal.classList.add('search-modal');modal.innerHTML=`<div class="global-search-field">${icon('search')}<input type="search" id="global-search" placeholder="Что нужно найти?" aria-label="Быстрый поиск"><kbd>ESC</kbd><button class="icon-btn" data-action="close-modal" aria-label="Закрыть поиск">${icon('close')}</button></div><div id="global-results" class="search-results"></div><div class="search-footer"><span>Ищем в заголовках, тексте и метках</span><span>${published().length} статей в базе</span></div>`;modal.removeAttribute('aria-labelledby');modal.setAttribute('aria-label','Поиск по базе знаний');const results=q=>{$('#global-results').innerHTML=(q?searchArticles(q):sortedArticles()).slice(0,7).map(a=>`<a class="search-result" href="#/article/${a.id}">${categoryIcon(a.category)}<div><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p></div>${icon('chevron')}</a>`).join('')||emptyState('Ничего не нашлось','Попробуйте другие слова.','search');};results('');$('#global-search').addEventListener('input',e=>results(e.target.value));setTimeout(()=>$('#global-search')?.focus(),30);}
function showHistory(id){const a=article(id);if(!a)return;showModal('История изменений',`<p>${esc(a.title)} · ${a.revisions.length} ${a.revisions.length===1?'версия':'версии'}</p>${[...a.revisions].reverse().map((r,i)=>`<section class="revision"><div class="between"><h3>Версия ${r.version}</h3>${i===0?'<span class="badge">Текущая</span>':''}</div><p>${esc(r.note)}</p><time>${r.date} · ${esc(r.author)} · действует с ${formatDate(r.effective)}</time><div class="flex gap8"><button class="btn btn-small" data-action="view-version" data-id="${id}" data-version="${r.version}">${icon('eye')}Посмотреть</button>${i>0?`<button class="btn btn-small" data-action="restore-version" data-id="${id}" data-version="${r.version}">${icon('history')}Восстановить</button>`:''}</div></section>`).join('')}`);}
function showIntegration(id){const r=integrations[id];if(!r)return;showModal(r.name,`<div class="notice">${icon('link')}Интеграция ещё не подключена</div><p>${r.detail}</p><div class="modal-footer"><button class="btn" data-action="close-modal">Понятно</button><a class="btn btn-primary" href="#/settings?tab=integrations">Настройки ${icon('arrow')}</a></div>`);}

function showAddUser(){showModal('Добавить сотрудника',`<form id="user-form"><div class="field"><label for="user-name">Имя и фамилия</label><input id="user-name" required maxlength="100" placeholder="Например: Иван Петров"></div><div class="field"><label for="user-email">Рабочая почта</label><input id="user-email" type="email" required maxlength="200" placeholder="name@example.test"></div><div class="field"><label for="user-role">Роль</label><select id="user-role"><option value="user">Сотрудник поддержки</option><option value="admin">Администратор</option></select></div><div id="user-error"></div><div class="modal-footer"><button type="button" class="btn" data-action="close-modal">Отмена</button><button type="submit" class="btn btn-primary">Добавить</button></div></form>`);$('#user-form').addEventListener('submit',e=>{e.preventDefault();safely(async()=>{const name=$('#user-name').value.trim(),email=$('#user-email').value.trim().toLowerCase(),role=$('#user-role').value;if(!name){$('#user-name').focus();return;}if(state.users.some(u=>u.email.toLowerCase()===email)){$('#user-error').innerHTML='<p class="form-error">Сотрудник с такой почтой уже добавлен.</p>';return;}await update(s=>s.users.push({id:crypto.randomUUID(),name,email,role,initials:initials(name)}));closeModal();renderSettings();toast('Сотрудник добавлен');});});}
function showLinkForm(id=''){
 const existing=state.links.find(link=>link.id===id),link=existing||{id:crypto.randomUUID(),title:'',url:'',description:''};
 showModal(existing?'Изменить ссылку':'Добавить ссылку',`<form id="resource-form"><div class="field"><label for="resource-title">Название</label><input id="resource-title" required maxlength="100" placeholder="Например: внутренний портал" value="${esc(link.title)}"></div><div class="field"><label for="resource-url">Адрес</label><input id="resource-url" type="url" required placeholder="https://…" value="${esc(link.url)}"></div><div class="field"><label for="resource-description">Короткое описание</label><textarea id="resource-description" rows="2" maxlength="300" placeholder="Для чего нужен этот ресурс?">${esc(link.description)}</textarea></div><p class="tiny muted">Ссылка хранится в общей базе и доступна команде.</p><div class="modal-footer"><button type="button" class="btn" data-action="close-modal">Отмена</button><button type="submit" class="btn btn-primary">Сохранить</button></div></form>`);
 $('#resource-form').addEventListener('submit',e=>{e.preventDefault();safely(async()=>{const title=$('#resource-title').value.trim(),url=$('#resource-url').value.trim(),description=$('#resource-description').value.trim();if(!title)return;if(!/^https?:\/\//i.test(url)){toast('Укажите адрес с http:// или https://');return;}await update(s=>{const item=s.links.find(x=>x.id===id);if(item)Object.assign(item,{title,url,description});else s.links.push({id:link.id,title,url,description});});closeModal();renderResources();toast(existing?'Ссылка обновлена':'Ссылка добавлена');});});
}
function showAddLink(){showLinkForm();}
function closeMenu(){const sidebar=$('.sidebar');sidebar?.classList.remove('open');syncSidebar();$('.sidebar-backdrop')?.remove();syncScrollLock();$('.mobile-menu')?.setAttribute('aria-expanded','false');}
