document.addEventListener('click',e=>{
 const button=e.target.closest('[data-action]');
 if(!button){if(e.target.closest('.modal a[href^="#/"]'))closeModal();if(e.target.closest('.sidebar a'))closeMenu();return;}
 const action=button.dataset.action,id=button.dataset.id;
 if(action==='toc'){e.preventDefault();document.getElementById(id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});return;}
 safely(async()=>{
  switch(action){
   case 'search':openSearch();break;
   case 'close-modal':closeModal();break;
   case 'menu':$('.sidebar').classList.add('open');syncSidebar();syncScrollLock();button.setAttribute('aria-expanded','true');{const backdrop=document.createElement('div');backdrop.className='sidebar-backdrop';backdrop.dataset.action='close-menu';$('#app').append(backdrop);$('.sidebar a')?.focus();}break;
   case 'close-menu':closeMenu();break;
   case 'centers':showModal('Рабочие пространства',`<p>Выберите бизнес-центр для контекста базы знаний.</p><div class="center-option"><span class="category-icon green">${icon('building')}</span><div><h3>БЦ «Горизонт»</h3><p>Текущий рабочий центр</p></div><span class="badge">Выбран</span></div><div class="center-option"><span class="category-icon">${icon('plus')}</span><div><h3>Другой бизнес-центр</h3><p>Добавление через каталог</p></div></div>`);break;
   case 'profile':showModal('Ваш профиль',`<div class="flex gap12" style="margin-bottom:24px"><span class="avatar green" style="width:50px;height:50px;font-size:16px">АМ</span><div><h3>Алексей Морозов</h3><p class="tiny muted">Администратор</p></div></div><div class="notice">${icon('info')}Управление командой и настройками ИИ доступно администраторам.</div><a class="btn btn-primary" href="#/settings?tab=users">${icon('users')}Управление командой</a>`);break;
   case 'notifications':showModal('Что нового в базе',`<p>Последние публикации и изменения базы знаний.</p>${sortedArticles().slice(0,5).map(a=>`<div class="notification-item"><span class="badge neutral">${a.date}</span><h3 style="margin-top:9px">${esc(a.title)}</h3><p>${esc(a.revisions.at(-1)?.note||'Добавлена статья')}</p><a class="text-link" href="#/article/${a.id}">Открыть материал ${icon('arrow')}</a></div>`).join('')}`);break;
   case 'favorite':{const exists=state.favorites.includes(id);await update(s=>{s.favorites=exists?s.favorites.filter(x=>x!==id):[...s.favorites,id];});if(page==='favorites')updateLibrary();else if(page==='knowledge')updateLibrary();else if(page==='article')renderArticle();toast(exists?'Убрано из избранного':'Добавлено в избранное');break;}
   case 'category-filter':params.set('category',id);document.querySelectorAll('[data-action="category-filter"]').forEach(b=>b.classList.toggle('active',b.dataset.id===id));updateLibrary();break;
   case 'integration':showIntegration(id);break;
   case 'history':showHistory(id);break;
   case 'view-version':{const a=article(id),r=a?.revisions.find(r=>r.version===Number(button.dataset.version));if(r)showModal(`Версия ${r.version} · ${r.date}`,`<p>${esc(r.note)} · ${esc(r.author)}</p><div class="prose revision-content">${sanitize(r.body)}</div><div class="modal-footer"><button class="btn" data-action="history" data-id="${id}">${icon('back')}К истории</button></div>`,true);break;}
   case 'restore-version':{const a=article(id),r=a.revisions.find(r=>r.version===Number(button.dataset.version));if(!r)return;const date=dateLabel();await update(s=>{const item=s.articles.find(x=>x.id===id);const revision={...r,version:item.revisions.length+1,date,author:'Алексей Морозов',note:`Восстановлена версия ${r.version}`};Object.assign(item,{title:r.title||item.title,summary:r.summary||item.summary,body:r.body,effective:r.effective,category:r.category||item.category,department:r.department||item.department,tags:r.tags||item.tags,date,author:revision.author});item.revisions.push(revision);});closeModal();renderArticle();toast('Версия восстановлена. Предыдущая сохранена в истории.');break;}
   case 'copy-link':{const url=location.origin+location.pathname+`#/article/${id}`;try{await navigator.clipboard.writeText(url);toast('Ссылка на статью скопирована');}catch{showModal('Ссылка на статью',`<div class="field"><label for="copy-url">Скопируйте адрес</label><input readonly id="copy-url" value="${esc(url)}"></div>`);$('#copy-url').select();}break;}
   case 'helpful':await update(s=>{s.helpful||=[];if(!s.helpful.includes(id))s.helpful.push(id);});button.innerHTML=`${icon('check')}Спасибо за отзыв`;button.disabled=true;toast('Спасибо! Отзыв сохранён в этом браузере.');break;
   case 'preview':{const d=collectDraft();if(!d)return;showModal('Предпросмотр инструкции',`<h1 style="font-size:27px;margin-bottom:18px">${esc(d.title||'Без названия')}</h1><p>${esc(d.summary)}</p><div class="prose">${sanitize(d.body)}</div>`,true);break;}
   case 'publish':await publish();break;
   case 'publish-anyway':await publish(true);break;
   case 'unlink':closeModal();editorInstance?.chain().focus().extendMarkRange('link').unsetLink().run();break;
   case 'suggest':$('#ai-query').value=button.dataset.query;runAssistantSearch();$('#ai-query').focus();break;
   case 'provider':await update(s=>{s.settings.provider=id;});renderSettings();toast('Будущий режим сохранён. Провайдер ещё не подключён.');break;
   case 'add-user':showAddUser();break;
   case 'add-link':showAddLink();break;
   case 'edit-link':showLinkForm(id);break;
   case 'delete-user':confirmDelete('user',id);break;
   case 'delete-draft':confirmDelete('draft',id);break;
   case 'delete-link':confirmDelete('link',id);break;
   case 'confirm-delete':{const kind=button.dataset.kind;await update(s=>{if(kind==='user'&&id!=='u1')s.users=s.users.filter(u=>u.id!==id);if(kind==='draft')delete s.drafts[id];if(kind==='link')s.links=s.links.filter(l=>l.id!==id);});closeModal();if(kind==='user')renderSettings();if(kind==='draft')renderLibrary();if(kind==='link')renderResources();toast('Запись удалена');break;}
   case 'export':exportData();toast('Резервная копия подготовлена');break;
  }
 });
});
document.addEventListener('keydown',e=>{
 if(e.defaultPrevented)return;
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();return;}
 if(e.key==='Escape'){closeModal();closeMenu();}
 if(e.key==='Tab'){
  const container=$('.modal')||($('.sidebar.open')||null);if(!container)return;
  const focusables=[...container.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea,[tabindex="0"]')].filter(el=>el.getClientRects().length);
  if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);
  if(e.shiftKey&&(document.activeElement===first||!container.contains(document.activeElement))){e.preventDefault();last.focus();}
  else if(!e.shiftKey&&(document.activeElement===last||!container.contains(document.activeElement))){e.preventDefault();first.focus();}
 }
});
let routeTicket=0;
async function route(){
 const ticket=++routeTicket;
 clearTimeout(draftTimer);
 if(editorInstance){await saveDraft();editorInstance.destroy();editorInstance=null;}
 closeModal();closeMenu();disposeOffice();disposeVault();
 const [path,query]=location.hash.replace(/^#\/?/,'').split('?');const parts=path.split('/');page=parts[0]||'';currentArticleId=parts[1]||null;params=new URLSearchParams(query||'');
 shell();window.scrollTo(0,0);
 switch(page){case '':renderHome();break;case 'knowledge':case 'favorites':renderLibrary();break;case 'article':renderArticle();break;case 'editor':await renderEditor();break;case 'people':renderPeople();break;case 'map':renderMap();break;case 'vault':mountVault({titleRow,footer,esc,icon,showModal,closeModal,toast});break;case 'resources':renderResources();break;case 'glossary':renderGlossary();break;case 'assistant':renderAssistant();break;case 'settings':renderSettings();break;case 'start':renderStart();break;default:$('#main-content').innerHTML=emptyState('Такой страницы пока нет','Перейдите в базу знаний или вернитесь на главную.','compass','На главную','#/');}
 if(ticket!==routeTicket)return;
 document.title=`${page==='article'&&article(currentArticleId)?article(currentArticleId).title+' — ':''}Компас · база знаний IT-поддержки`;
}
window.addEventListener('hashchange',()=>safely(route));
window.addEventListener('pagehide',()=>{if(editorInstance){clearTimeout(draftTimer);saveDraft().catch(()=>{});}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&editorInstance)safely(saveDraft);});
await initialize();
installCopying({toast,resolveSecret:id=>state.demoCredentials[id],resolveVault:resolveVaultValue});
await safely(route);
if(!persistent)toast('Хранилище браузера недоступно. Изменения пока нельзя сохранить.');
